import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{buildPhoto}from './photo-meshes.js?v=20261023-physicscomplete01';import{photoFigure}from './photo-figures.js?v=20261023-physicscomplete01';
export function showPhoto(scene,w={}){let[kind,state]=scene.split(':'),names={chloroplast:'Light energy enters the chloroplast',ledger:'Conserve matter; transfer energy',factor:'Change one condition',limits:'Compare the conditions',lamp:'Distance changes light intensity',greenhouse:'Rate and profit are different',apparatus:'Measure oxygen over time',graph:'Plot the observed rates',bubbles:'Count is not volume',uses:'Put glucose to use'},o={kind,state:state||'light',revealed:true,...w},name=w.title||names[kind]||'Investigate photosynthesis';if(kind==='factor'&&!o.factor)o.factor=state;let figure=photoFigure({...o,title:name});if(['graph','limits'].includes(kind)){renderDiagram(name,w.stateLabel||'Original illustrative evidence',figure,'PHOTOSYNTHESIS EVIDENCE');return;}renderCustomModel({name,formula:w.stateLabel||'Inspect; switch to the labelled diagram',kicker:'SCHEMATIC BIOLOGY MODEL',aria:name+'. Symbolic geometry; labelled diagram available.',atoms:[],bonds:[],radius:2.6,viewKey:'photo-'+kind,startPaused:true,note:'Original model · not measured biological scale/rate',diagram:figure,build:(g,T)=>buildPhoto(g,T,o)});}
